-- Objective brief state: human-facing descriptions, independent title and
-- description ownership, current-instruction authorship, durable generation
-- intent and removal suppression (coo:1275, contract ADR 0057). Same semantics
-- as the Postgres migration of the same name.
--
-- Every column is additive and nullable or defaulted, so existing rows keep
-- their meaning:
--
-- * `title_source` stays NULL on existing rows. NULL means "provenance not
--   known"; services treat it as owned and never replace it automatically.
-- * Descriptions start empty. No summary is generated by this migration.
-- * `instruction_author_kind` is backfilled only where creation provenance
--   still describes the current instruction text: a live row with non-blank
--   instructions whose change feed records no instruction edit. Every other
--   row stays NULL (unknown authorship), which never qualifies for an
--   automatic summary.
-- * `revision` and `updated_at` are not moved: no observable field changes.

PRAGMA foreign_keys = ON;

ALTER TABLE objectives ADD COLUMN title_source TEXT
  CHECK (title_source IS NULL OR title_source IN ('generated', 'agent', 'user'));
ALTER TABLE objectives ADD COLUMN title_generation INTEGER NOT NULL DEFAULT 0
  CHECK (title_generation >= 0);
ALTER TABLE objectives ADD COLUMN title_status TEXT
  CHECK (title_status IS NULL OR title_status IN ('pending', 'failed'));

ALTER TABLE objectives ADD COLUMN description TEXT;
ALTER TABLE objectives ADD COLUMN description_source TEXT
  CHECK (description_source IS NULL OR description_source IN ('generated', 'agent', 'user'));
ALTER TABLE objectives ADD COLUMN description_instruction_hash TEXT;
ALTER TABLE objectives ADD COLUMN description_author_workspace_user_id TEXT;
ALTER TABLE objectives ADD COLUMN description_author_agent TEXT;
ALTER TABLE objectives ADD COLUMN description_updated_at TEXT
  CHECK (description_updated_at IS NULL OR description_updated_at GLOB '????-??-??T??:??:??.???Z');
ALTER TABLE objectives ADD COLUMN description_revision INTEGER NOT NULL DEFAULT 0
  CHECK (description_revision >= 0);
ALTER TABLE objectives ADD COLUMN description_suppressed INTEGER NOT NULL DEFAULT 0
  CHECK (description_suppressed IN (0, 1));
ALTER TABLE objectives ADD COLUMN description_generation INTEGER NOT NULL DEFAULT 0
  CHECK (description_generation >= 0);
ALTER TABLE objectives ADD COLUMN description_status TEXT
  CHECK (description_status IS NULL OR description_status IN ('pending', 'failed'));
ALTER TABLE objectives ADD COLUMN description_request_kind TEXT
  CHECK (description_request_kind IS NULL OR description_request_kind IN ('automatic', 'explicit'));
ALTER TABLE objectives ADD COLUMN description_failure_code TEXT;

ALTER TABLE objectives ADD COLUMN instruction_author_kind TEXT
  CHECK (instruction_author_kind IS NULL OR instruction_author_kind IN ('human', 'agent', 'automation'));

UPDATE objectives
   SET instruction_author_kind = created_by_kind
 WHERE deleted_at IS NULL
   AND TRIM(COALESCE(instruction_text, '')) <> ''
   AND NOT EXISTS (
     SELECT 1
       FROM entity_changes ec
      WHERE ec.entity_type = 'objective'
        AND ec.entity_id = objectives.id
        AND ec.operation = 'update'
        AND ec.changed_fields_json LIKE '%"instruction_text"%'
   );
